import React, { useState, useEffect, useRef } from 'react';
import { io } from 'socket.io-client';

function LaptopWebcamFeed() {
  const videoRef = useRef(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    navigator.mediaDevices.getUserMedia({ video: true })
      .then(stream => {
        if (videoRef.current) videoRef.current.srcObject = stream;
      })
      .catch(() => setError("Camera permission denied or camera in use."));

    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        videoRef.current.srcObject.getTracks().forEach(track => track.stop());
      }
    };
  }, []);

  if (error) return <div style={{ color: '#f87171', padding: '1rem', textAlign: 'center' }}>{error}</div>;

  return (
    <video
      ref={videoRef}
      autoPlay
      playsInline
      muted
      style={{ width: '100%', height: '180px', objectFit: 'cover', borderRadius: '8px' }}
    />
  );
}

export default function Dashboard({ token }) {
  const [cameras, setCameras] = useState([]);
  const [userEmail, setUserEmail] = useState('');
  const [emailSavedMsg, setEmailSavedMsg] = useState('');
  const [evidenceLogs, setEvidenceLogs] = useState([]);

  useEffect(() => {
    if ('Notification' in window && Notification.permission !== 'granted') {
      Notification.requestPermission();
    }

    // Fetch active cameras
    fetch('http://localhost:5000/api/cameras', { headers: { 'Authorization': `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => setCameras(data));

    // Fetch current settings
    fetch('http://localhost:5000/api/settings', { headers: { 'Authorization': `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => setUserEmail(data.email || ''));

    // Fetch initial evidence logs
    fetch('http://localhost:5000/api/evidence', { headers: { 'Authorization': `Bearer ${token}` } })
      .then(res => res.json())
      .then(data => setEvidenceLogs(data));

    // Listen to Real-Time AI Detection Alerts via Socket.IO
    const socket = io('http://localhost:5000');
    socket.on('new-alert', (newLog) => {
      setEvidenceLogs(prev => [newLog, ...prev]);

      // Trigger Web Desktop Notification
      if (Notification.permission === 'granted') {
        new Notification("🚨 Real-Time AI Security Alert", {
          body: `${newLog.alertType} on ${newLog.cameraName}`,
        });
      }
    });

    return () => socket.disconnect();
  }, [token]);

  const handleSaveEmail = (e) => {
    e.preventDefault();
    fetch('http://localhost:5000/api/settings', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
      body: JSON.stringify({ email: userEmail })
    }).then(() => {
      setEmailSavedMsg('Alert recipient email updated!');
      setTimeout(() => setEmailSavedMsg(''), 3000);
    });
  };

  const handleDeleteCamera = (id) => {
    fetch(`http://localhost:5000/api/cameras/${id}`, {
      method: 'DELETE',
      headers: { 'Authorization': `Bearer ${token}` }
    }).then(() => setCameras(cameras.filter(c => c.id !== id)));
  };

  // --- DYNAMIC REAL-TIME WEEKLY ANALYTICS CALCULATION ---
  const daysOfWeek = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const dayCounts = { Mon: 0, Tue: 0, Wed: 0, Thu: 0, Fri: 0, Sat: 0, Sun: 0 };
  let totalDetections = evidenceLogs.length;
  let criticalThreats = 0;

  evidenceLogs.forEach(log => {
    const date = new Date(log.timestamp);
    const dayName = daysOfWeek[date.getDay()];
    if (dayCounts[dayName] !== undefined) {
      dayCounts[dayName] += 1;
    }
    if (log.alertType && (log.alertType.includes('KNIFE') || log.alertType.includes('FIRE') || log.alertType.includes('CRITICAL'))) {
      criticalThreats += 1;
    }
  });

  // Calculate Peak Activity Day
  let peakDay = 'None';
  let maxCount = -1;
  Object.keys(dayCounts).forEach(day => {
    if (dayCounts[day] > maxCount && dayCounts[day] > 0) {
      maxCount = dayCounts[day];
      peakDay = day;
    }
  });

  const maxChartVal = Math.max(...Object.values(dayCounts), 1);

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '2rem' }}>

      {/* EMAIL CONFIGURATION CARD */}
      <div className="card" style={{ background: '#1e293b', borderLeft: '4px solid #38bdf8' }}>
        <h3>⚙️ Alert Notification Configuration</h3>
        <p style={{ color: '#94a3b8', fontSize: '0.9rem', margin: '0.5rem 0 1rem 0' }}>
          Specify your email address below to automatically receive security logs and live alerts.
        </p>

        {emailSavedMsg && <div className="message-banner success">{emailSavedMsg}</div>}

        <form onSubmit={handleSaveEmail} style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
          <div className="form-group" style={{ flex: 1, marginBottom: 0 }}>
            <input
              type="email"
              placeholder="enter.your.email@gmail.com"
              value={userEmail}
              onChange={e => setUserEmail(e.target.value)}
              required
            />
          </div>
          <button type="submit" className="btn-primary" style={{ width: 'auto', marginTop: 0, padding: '0.75rem 1.5rem' }}>
            Save Email
          </button>
        </form>
      </div>

      {/* CAMERA STREAMS SECTION */}
      <div>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
          <h2>Connected Stream Feeds ({cameras.length})</h2>
          <span style={{ color: '#34d399', fontWeight: '600' }}>● AI Multi-Model Inference Active</span>
        </div>

        {cameras.length === 0 ? (
          <div className="card" style={{ textAlign: 'center', padding: '3rem' }}>
            <p style={{ color: '#94a3b8' }}>No active camera streams configured.</p>
          </div>
        ) : (
          <div className="camera-grid">
            {cameras.map((cam) => (
              <div key={cam.id} className="card camera-card">
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                  <h3>{cam.name}</h3>
                  <span className="location-badge">{cam.locationType}</span>
                </div>

                <div className="feed-box" style={{ padding: 0, position: 'relative', overflow: 'hidden' }}>
                  <span className="live-tag" style={{ zIndex: 10 }}>LIVE FEED</span>
                  {cam.rtspUrl === '0' ? <LaptopWebcamFeed /> : <div style={{ padding: '2rem', textAlign: 'center' }}>RTSP Stream: {cam.rtspUrl}</div>}
                </div>

                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.75rem' }}>
                  <p style={{ fontSize: '0.8rem', color: '#64748b' }}>
                    Source: {cam.rtspUrl === '0' ? 'Built-in Webcam' : cam.rtspUrl}
                  </p>
                  <button onClick={() => handleDeleteCamera(cam.id)} style={{ background: 'none', border: 'none', color: '#f87171', cursor: 'pointer', fontSize: '0.8rem' }}>
                    Remove Stream
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* DYNAMIC REAL-TIME WEEKLY ANALYSIS SECTION */}
      <div className="card" style={{ background: '#0f172a', borderColor: '#334155', marginTop: '1rem' }}>
        <h3 style={{ color: '#38bdf8', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
          📊 Real-Time Dynamic Weekly Incident Analysis
        </h3>

        {/* Dynamic Metric Badges */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '1rem', marginBottom: '1.5rem' }}>
          <div style={{ background: '#1e293b', padding: '1rem', borderRadius: '8px', borderLeft: '4px solid #f59e0b' }}>
            <span style={{ color: '#94a3b8', fontSize: '0.8rem' }}>Total Detections</span>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#f8fafc', margin: '0.2rem 0 0 0' }}>{totalDetections}</p>
          </div>
          <div style={{ background: '#1e293b', padding: '1rem', borderRadius: '8px', borderLeft: '4px solid #ef4444' }}>
            <span style={{ color: '#94a3b8', fontSize: '0.8rem' }}>Critical Threats (Knife/Fire)</span>
            <p style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#f8fafc', margin: '0.2rem 0 0 0' }}>{criticalThreats}</p>
          </div>
          <div style={{ background: '#1e293b', padding: '1rem', borderRadius: '8px', borderLeft: '4px solid #10b981' }}>
            <span style={{ color: '#94a3b8', fontSize: '0.8rem' }}>AI Status</span>
            <p style={{ fontSize: '1.2rem', fontWeight: 'bold', color: '#34d399', margin: '0.2rem 0 0 0' }}>Active Live</p>
          </div>
          <div style={{ background: '#1e293b', padding: '1rem', borderRadius: '8px', borderLeft: '4px solid #3b82f6' }}>
            <span style={{ color: '#94a3b8', fontSize: '0.8rem' }}>Peak Activity Day</span>
            <p style={{ fontSize: '1.2rem', fontWeight: 'bold', color: '#f8fafc', margin: '0.2rem 0 0 0' }}>{peakDay}</p>
          </div>
        </div>

        {/* Dynamic Bar Graph */}
        <h4 style={{ color: '#94a3b8', marginBottom: '0.75rem', fontSize: '0.9rem' }}>Incident Frequency Breakdown</h4>
        <div style={{ display: 'flex', alignItems: 'flex-end', gap: '1rem', height: '120px', padding: '1rem 0', borderBottom: '1px solid #334155' }}>
          {['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'].map((day) => {
            const count = dayCounts[day];
            const heightPercent = maxChartVal > 0 ? (count / maxChartVal) * 100 : 0;
            return (
              <div key={day} style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', height: '100%', justifyContent: 'flex-end' }}>
                <span style={{ fontSize: '0.75rem', color: '#38bdf8', marginBottom: '0.25rem' }}>{count}</span>
                <div
                  style={{
                    width: '100%',
                    maxWidth: '30px',
                    height: `${Math.max(heightPercent, 5)}%`,
                    background: count > 0 ? 'linear-gradient(180deg, #38bdf8 0%, #1e40af 100%)' : '#1e293b',
                    borderRadius: '4px 4px 0 0',
                    transition: 'height 0.4s ease'
                  }}
                />
                <span style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.5rem' }}>{day}</span>
              </div>
            );
          })}
        </div>
      </div>

    </div>
  );
}
